library(shiny)
library(bslib)

ui <- page_navbar(
  title = "Vector Subspaces & Linear Independence Lab",
  theme = bs_theme(
    version = 5,
    bootswatch = "flatly",
    primary = "#1e293b",
    secondary = "#475569",
    success = "#16a34a",
    danger = "#dc2626"
  ),
  header = tags$head(
    tags$style(HTML("
      body { background-color: #f8fafc; font-family: 'Inter', system-ui, -apple-system, sans-serif; }
      .lab-container { max-width: 1360px; margin: 0 auto; padding: 10px 16px; }
      .level-bar { display: flex; flex-wrap: wrap; gap: 6px; margin-bottom: 12px; align-items: center; }
      .lvl-btn {
        border: 1.5px solid #cbd5e1; background: #ffffff; color: #334155;
        padding: 5px 11px; border-radius: 8px; font-weight: 600; font-size: 0.84rem;
        cursor: pointer; transition: all 0.15s ease; display: flex; align-items: center; gap: 5px;
      }
      .lvl-btn:hover { border-color: #64748b; background: #f1f5f9; }
      .lvl-btn.active { background: #1e293b; color: #ffffff; border-color: #1e293b; }
      .lvl-btn.done { border-color: #16a34a; background: #f0fdf4; color: #15803d; }
      .lvl-btn.done.active { background: #15803d; color: #ffffff; border-color: #15803d; }
      .dim-tag {
        font-size: 0.68rem; padding: 1px 5px; border-radius: 4px;
        background: #e2e8f0; color: #475569; font-weight: 700;
      }
      .lvl-btn.active .dim-tag { background: rgba(255,255,255,0.22); color: #fff; }
      .workspace-grid { display: grid; grid-template-columns: 360px 1fr; gap: 16px; align-items: start; }
      @media (max-width: 992px) { .workspace-grid { grid-template-columns: 1fr; } }
      .control-card, .canvas-card {
        background: #ffffff; border-radius: 12px; border: 1px solid #e2e8f0;
        box-shadow: 0 2px 6px rgba(15, 23, 42, 0.04); padding: 16px;
      }
      .canvas-card { padding: 12px; position: relative; }
      .zoom-bar { position: absolute; top: 20px; right: 20px; display: flex; gap: 4px; z-index: 2; }
      .zoom-btn {
        min-width: 32px; height: 32px; border-radius: 6px; border: 1px solid #cbd5e1;
        background: rgba(255,255,255,0.92); color: #1e293b; font-weight: 700; font-size: 1.05rem; cursor: pointer;
      }
      .zoom-btn:hover { background: #f1f5f9; border-color: #64748b; }
      .zoom-reset { font-size: 0.78rem; padding: 0 9px; }
      canvas#vecCanvas {
        width: 100%; height: 560px; display: block; border-radius: 8px;
        background: #ffffff; border: 1px solid #e2e8f0; cursor: grab; touch-action: none;
      }
      canvas#vecCanvas:active { cursor: grabbing; }
      .status-pill {
        padding: 9px 13px; border-radius: 8px; font-weight: 600; font-size: 0.88rem;
        margin-bottom: 12px; border: 1.5px solid transparent; transition: all 0.2s ease;
      }
      .pill-neutral { background: #f1f5f9; color: #334155; border-color: #cbd5e1; }
      .pill-success { background: #dcfce7; color: #166534; border-color: #86efac; }
      .pill-danger  { background: #fee2e2; color: #991b1b; border-color: #fca5a5; }
      .pill-warning { background: #fef3c7; color: #92400e; border-color: #fde68a; }
      .vec-readout {
        font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
        font-size: 0.82rem; background: #f8fafc; border: 1px solid #e2e8f0;
        border-radius: 8px; padding: 10px; margin-bottom: 12px;
      }
      .vec-row { display: flex; justify-content: space-between; padding: 3px 0; border-bottom: 1px dashed #e2e8f0; }
      .vec-row:last-child { border-bottom: none; }
      .action-stack { display: flex; flex-direction: column; gap: 8px; }
      .btn-lab {
        padding: 9px 14px; border-radius: 8px; font-weight: 600; font-size: 0.9rem;
        border: none; cursor: pointer; transition: all 0.15s; text-align: center;
      }
      .btn-solve { background: #2563eb; color: #ffffff; }
      .btn-solve:hover { background: #1d4ed8; }
      .btn-phase { background: #7c3aed; color: #ffffff; }
      .btn-phase:hover:not(:disabled) { background: #6d28d9; }
      .btn-phase:disabled { background: #cbd5e1; color: #64748b; cursor: not-allowed; }
      .btn-imposs { background: #f59e0b; color: #ffffff; }
      .btn-imposs:hover { background: #d97706; }
      .btn-reset { background: #e2e8f0; color: #334155; }
      .btn-reset:hover { background: #cbd5e1; }
      .popup-box {
        margin-top: 12px; padding: 12px 14px; border-radius: 8px;
        font-size: 0.88rem; display: none;
      }
      .popup-red { background: #fef2f2; border: 1.5px solid #f87171; color: #991b1b; }
      .popup-green { background: #f0fdf4; border: 1.5px solid #4ade80; color: #166534; }
      .popup-quiz { background: #eff6ff; border: 1.5px solid #60a5fa; color: #1e3a8a; }
      .mc-option {
        display: block; width: 100%; text-align: left; margin-top: 7px;
        padding: 8px 11px; border-radius: 6px; border: 1px solid #bfdbfe;
        background: #ffffff; color: #1e293b; font-size: 0.84rem; cursor: pointer;
      }
      .mc-option:hover { background: #dbeafe; border-color: #3b82f6; }
      .mc-option.wrong { background: #fee2e2; border-color: #ef4444; color: #991b1b; }
      .mc-option.correct { background: #dcfce7; border-color: #22c55e; color: #166534; font-weight: 700; }
      .help-strip {
        font-size: 0.79rem; color: #475569; background: #f8fafc;
        border: 1px solid #e2e8f0; border-radius: 8px; padding: 8px 12px; margin-top: 10px;
      }
      .phase-badge {
        display: inline-block; padding: 3px 9px; border-radius: 999px;
        font-size: 0.76rem; font-weight: 700; text-transform: uppercase; margin-bottom: 6px;
      }
      .phase-1 { background: #ede9fe; color: #6d28d9; }
      .phase-2 { background: #dbeafe; color: #1d4ed8; }
      .receipt-card {
        background: #ffffff; border: 1px solid #e2e8f0; border-radius: 10px;
        padding: 16px; margin-bottom: 14px;
      }
    "))
  ),

  nav_panel(
    title = "1. Reach the Target (Subspaces)",
    value = "panel1",
    div(class = "lab-container", id = "mount-panel1")
  ),
  nav_panel(
    title = "2. Escape the Set (Is It a Subspace?)",
    value = "panel2",
    div(class = "lab-container", id = "mount-panel2")
  ),
  nav_panel(
    title = "3. Back to the Origin (Linear Dependence)",
    value = "panel3",
    div(class = "lab-container", id = "mount-panel3")
  ),
  nav_panel(
    title = "Lecture Preview",
    value = "panel4",
    div(
      class = "lab-container",
      h4("What You Just Discovered (and What We Will Call It in Lecture)"),
      p(class = "text-muted", "Play with the three panels first. In lecture we will put names and definitions on everything you saw. Here is a sneak peek."),
      div(
        class = "receipt-card",
        h5("1. Vector Subspaces (Panel 1: Reach the Target)"),
        p(HTML("<strong>What you saw:</strong> Stretching one vector only reached points on a line through the origin. Two vectors that were <em>not collinear</em> could reach any point in the plane, but two <em>collinear</em> vectors were stuck on a single line. In 3D, two vectors reached a plane, and it took three to fill all of 3D.")),
        p(HTML("<strong>In lecture:</strong> A <strong>vector subspace</strong> is the set of all points that you can reach by stretching and combining a collection of vectors. For example, the subspace of <strong>b</strong> = (2, 2) is B = { λ<strong>b</strong> = (2λ, 2λ) : λ ∈ ℝ }, a line. The larger space the subspace sits inside (ℝ² or ℝ³ here) is called the <strong>ambient space</strong>."))
      ),
      div(
        class = "receipt-card",
        h5("2. Checking Whether a Set Is a Subspace (Panel 2: Escape the Set)"),
        p(HTML("<strong>What you saw:</strong> Some sets could be escaped with λ = 0 (the line that misses the origin), some with a negative λ (Quadrant I), and some by adding two vectors (the two axes, Quadrants I and III). Lines and planes through the origin, and all of ℝ², could never be escaped.")),
        p(HTML("<strong>In lecture:</strong> A set V is a vector subspace if it satisfies all three conditions:<br>
        1. V <strong>contains the zero vector</strong>: <strong>0</strong> ∈ V<br>
        2. V is <strong>closed under scalar multiplication</strong>: for all λ ∈ ℝ and all <strong>v</strong> ∈ V, λ<strong>v</strong> ∈ V<br>
        3. V is <strong>closed under addition</strong>: for all <strong>v<sub>1</sub></strong>, <strong>v<sub>2</sub></strong> ∈ V, <strong>v<sub>1</sub></strong> + <strong>v<sub>2</sub></strong> ∈ V<br>
        Escaping the set in the app means you found a condition that fails."))
      ),
      div(
        class = "receipt-card",
        h5("3. Linear Independence and Dimensionality (Panel 3: Back to the Origin)"),
        p(HTML("<strong>What you saw:</strong> You could only get back to (0, 0) with at least one non-zero λ when some vector was a combination of the others: collinear vectors, three vectors in 2D, three vectors on one plane in 3D, or four vectors in 3D.")),
        p(HTML("<strong>In lecture:</strong> A collection <strong>v<sub>1</sub></strong>, ..., <strong>v<sub>m</sub></strong> is <strong>linearly independent</strong> if no vector in the collection is a linear combination of the others. It is <strong>linearly dependent</strong> if a linear combination λ<sub>1</sub><strong>v<sub>1</sub></strong> + ... + λ<sub>m</sub><strong>v<sub>m</sub></strong> can produce the zero vector with at least one λ<sub>j</sub> non-zero.<br>
        A collection of m vectors with dimension n, where d of the vectors are linearly independent, forms a <strong>d-dimensional subspace</strong>. If m &gt; n the collection <em>must</em> be linearly dependent; if m ≤ n it <em>may</em> be linearly independent, and you have to check."))
      )
    )
  ),

  footer = tags$script(HTML("
  (function() {
    // Shared DOM Template mounted smoothly into whichever panel is active
    const workspaceHTML = `
      <div class='level-bar' id='levelBar'></div>
      <div class='workspace-grid'>
        <div class='control-card'>
          <div id='phaseBadgeWrap'></div>
          <h5 id='lvlTitle' style='margin-bottom:4px; font-weight:700;'></h5>
          <p id='lvlPrompt' style='font-size:0.86rem; color:#475569; margin-bottom:10px;'></p>
          <div id='statusPill' class='status-pill pill-neutral'></div>
          <div id='vecReadout' class='vec-readout'></div>
          <div class='action-stack'>
            <button id='btnPhase' class='btn-lab btn-phase' style='display:none;'>Lock Vectors in Set & Enter Phase 2 →</button>
            <button id='btnCheck' class='btn-lab btn-solve'>Check Solution</button>
            <button id='btnImposs' class='btn-lab btn-imposs'>Declare Impossible</button>
            <button id='btnReset' class='btn-lab btn-reset'>Reset Level</button>
          </div>
          <div id='popupBox' class='popup-box'></div>
        </div>
        <div class='canvas-card'>
          <div class='zoom-bar'>
            <button id='btnZoomIn' class='zoom-btn' title='Zoom in'>+</button>
            <button id='btnZoomOut' class='zoom-btn' title='Zoom out'>&minus;</button>
            <button id='btnZoomReset' class='zoom-btn zoom-reset' title='Reset zoom and rotation'>Reset view</button>
          </div>
          <canvas id='vecCanvas' width='860' height='560'></canvas>
          <div id='helpStrip' class='help-strip'></div>
        </div>
      </div>
    `;

    // =========================================================================
    // 30-LEVEL CURRICULUM DATA (10 PER PANEL)
    // =========================================================================
    const LEVELS = {
      panel1: [
        {
          id: 1, dim: 2, title: 'Level 1: Stretching One Vector',
          prompt: 'Drag the head of v1 = (2, 2) to stretch it (multiply by a scalar λ) until its tip lands on Target T(-1, -1).',
          vecs: [[2, 2]], target: [-1, -1], possible: true,
          takeaway: 'Every point you can reach by stretching v1 lies on one line through the origin. That line is the subspace of v1.'
        },
        {
          id: 2, dim: 2, title: 'Level 2: Off the Line',
          prompt: 'Stretch v1 = (2, 2) to reach Target T(-1, 3), or declare it impossible.',
          vecs: [[2, 2]], target: [-1, 3], possible: false,
          mcQuestion: 'Why can you never reach T(-1, 3) by stretching v1 = (2, 2)?',
          mcOptions: [
            { text: 'Every stretch λ·v1 = (2λ, 2λ) has equal coordinates, so the reachable points form a line through the origin, and T is not on it.', correct: true },
            { text: 'Scalars λ are not allowed to be negative.', correct: false },
            { text: 'T is in Quadrant II, and only 3 vectors can reach Quadrant II.', correct: false }
          ],
          takeaway: 'The subspace of a single vector is a line through the origin: { λ·v1 : λ ∈ ℝ }. Points off that line are NOT in the subspace.'
        },
        {
          id: 3, dim: 2, title: 'Level 3: Stretching AND Combining',
          prompt: 'Stretch v1 = (1, 2) and v2 = (-2, 1), then drag their shafts to chain them tip-to-tail from the origin to T(-4, -3).',
          vecs: [[1, 2], [-2, 1]], target: [-4, -3], possible: true,
          takeaway: 'Because v1 and v2 are NOT collinear, stretching and combining them reaches every point of the plane ℝ².'
        },
        {
          id: 4, dim: 2, title: 'Level 4: Big Negative Stretches',
          prompt: 'Stretch v1 = (2, -1) and v2 = (1, 0) (negative λ flips direction!) and chain them tip-to-tail from (0, 0) to T(-5, 1).',
          vecs: [[2, -1], [1, 0]], target: [-5, 1], possible: true,
          takeaway: 'Two non-collinear vectors in 2D can reach any point, as long as you allow any real λ (including negative ones).'
        },
        {
          id: 5, dim: 2, title: 'Level 5: The Collinear Trap',
          prompt: 'You have 2 vectors in 2D: v1 = (2, 1) and v2 = (-4, -2). Reach T(1, 3) or declare it impossible.',
          vecs: [[2, 1], [-4, -2]], target: [1, 3], possible: false,
          mcQuestion: 'You have 2 vectors in 2D. Why can you still NOT reach T(1, 3)?',
          mcOptions: [
            { text: 'v2 = -2·v1, so the two vectors are collinear. Combining them still only reaches one line through the origin.', correct: true },
            { text: 'You always need at least 3 vectors to reach every point in 2D.', correct: false },
            { text: 'Adding vectors can never cross the x-axis.', correct: false }
          ],
          takeaway: 'Having 2 vectors in 2D is not enough on its own: if they are collinear, the subspace they create is only a line.'
        },
        {
          id: 6, dim: 2, title: 'Level 6: Collinear, but T is ON the Line',
          prompt: 'v1 = (1, 2) and v2 = (-2, -4) are collinear. Can you still reach T(-3, -6)? Chain from the origin!',
          vecs: [[1, 2], [-2, -4]], target: [-3, -6], possible: true, extent: 7,
          takeaway: 'Even with collinear vectors, any point that sits ON their shared line is still in their subspace. Because the vectors are collinear, there are many different λ combinations that work here. Try to find another one!'
        },
        {
          id: 7, dim: 3, title: 'Level 7: One Vector in 3D',
          prompt: 'In 3D: stretch v1 = (2, 1, 2) using its z-head or xy-floor handle to reach T(2, -3, 2).',
          vecs: [[2, 1, 2]], target: [2, -3, 2], possible: false,
          mcQuestion: 'Why can v1 = (2, 1, 2) never reach T(2, -3, 2)?',
          mcOptions: [
            { text: 'Stretching one vector only reaches a line through (0, 0, 0). That line is a tiny part of 3D space.', correct: true },
            { text: '3D vectors cannot be stretched by negative numbers.', correct: false },
            { text: 'T has a negative y-coordinate, which requires 4 vectors.', correct: false }
          ],
          takeaway: 'One vector creates a line (a 1-dimensional subspace) whether the ambient space is ℝ² or ℝ³.'
        },
        {
          id: 8, dim: 3, title: 'Level 8: A Plane Inside 3D',
          prompt: 'Stretch v1 = (2, 0, 1) and v2 = (0, 2, 1) and chain them tip-to-tail from (0, 0, 0) to hit T(4, 2, 3).',
          vecs: [[2, 0, 1], [0, 2, 1]], target: [4, 2, 3], possible: true,
          takeaway: 'Two non-collinear vectors in 3D create a plane through the origin, sitting inside the ambient space ℝ³.'
        },
        {
          id: 9, dim: 3, title: 'Level 9: Off the Plane in 3D',
          prompt: 'Try to reach T(2, 2, -2) using v1 = (2, 0, 1) and v2 = (0, 2, 1).',
          vecs: [[2, 0, 1], [0, 2, 1]], target: [2, 2, -2], possible: false,
          mcQuestion: 'Why is T(2, 2, -2) unreachable with v1 = (2, 0, 1) and v2 = (0, 2, 1)?',
          mcOptions: [
            { text: 'Combinations of v1 and v2 only reach the plane z = 0.5x + 0.5y, and T(2, 2, -2) is not on that plane.', correct: true },
            { text: 'v1 and v2 are collinear.', correct: false },
            { text: 'Targets with a negative z need 4 vectors.', correct: false }
          ],
          takeaway: 'With 2 vectors in a 3D ambient space, the most you can create is a 2-dimensional subspace (a plane), not all of ℝ³.'
        },
        {
          id: 10, dim: 3, title: 'Level 10: Filling All of 3D',
          prompt: 'Stretch v1, v2, v3 and chain all three tip-to-tail from (0, 0, 0) to reach T(-2, 4, 4).',
          vecs: [[2, 0, 0], [0, 2, 1], [0, 0, 2]], target: [-2, 4, 4], possible: true,
          takeaway: 'Three vectors in 3D that point in genuinely different directions reach every point of ℝ³.'
        }
      ],

      panel2: [
        {
          id: 1, dim: 2, title: 'Level 1: A Line That Misses the Origin',
          prompt: 'Phase 1: Place u and v on the blue line y = 0.5x + 2. Phase 2: Stretch or add them to land somewhere OFF the line.',
          setType: 'line_shifted', setName: 'V', ruleText: 'V = { (x, y) : y = 0.5x + 2 }',
          initVecs: [[0, 2], [2, 3]], possible: true,
          takeaway: 'A line that misses the origin actually fails ALL three conditions: it does not contain the zero vector, and it is not closed under scalar multiplication or addition. Finding any ONE failure is enough to show it is not a subspace.'
        },
        {
          id: 2, dim: 2, title: 'Level 2: A Line Through the Origin',
          prompt: 'Phase 1: Pick any u, v on y = -0.5x. Phase 2: Try to stretch or add them to escape the line!',
          setType: 'line_origin', setName: 'V', ruleText: 'V = { (x, y) : y = -0.5x }',
          initVecs: [[-2, 1], [4, -2]], possible: false,
          mcQuestion: 'Why is it impossible to escape the line y = -0.5x?',
          mcOptions: [
            { text: 'It contains (0, 0), and stretching or adding points on the line always lands back on the line. It passes every test, so it is a subspace.', correct: true },
            { text: 'You need 3 vectors to escape a line.', correct: false },
            { text: 'Lines with a negative slope trap vectors in Quadrants II and IV.', correct: false }
          ],
          takeaway: 'Every line through the origin is a vector subspace of ℝ². (It is exactly the set of points reachable by stretching one vector.)'
        },
        {
          id: 3, dim: 2, title: 'Level 3: A Line Segment',
          prompt: 'V is the piece of y = x with -2 ≤ x ≤ 2. Pick u, v in V, then stretch or add them to break out!',
          setType: 'segment', setName: 'V', ruleText: 'V = { (x, y) : y = x and -2 ≤ x ≤ 2 }',
          initVecs: [[1.5, 1.5], [1, 1]], possible: true,
          takeaway: 'The segment contains (0, 0), but a subspace cannot have edges: big enough stretches or sums always run off the end.'
        },
        {
          id: 4, dim: 2, title: 'Level 4: The First Quadrant',
          prompt: 'Q is Quadrant I (shaded). Pick u, v in Q, lock them in, and find a move that lands outside Q!',
          setType: 'quad1', setName: 'Q', ruleText: 'Q = { (x, y) : x, y ≥ 0 }',
          initVecs: [[2, 1], [1, 2]], possible: true,
          takeaway: 'Q contains (0, 0) and is closed under addition (adding non-negative numbers stays non-negative), but a negative λ flips vectors out of Q, so Q is NOT a subspace.'
        },
        {
          id: 5, dim: 2, title: 'Level 5: The Two Axes',
          prompt: 'V is the x-axis together with the y-axis. Hint: put u on one axis and v on the other in Phase 1!',
          setType: 'axes_union', setName: 'V', ruleText: 'V = { (x, y) : x = 0 or y = 0 }',
          initVecs: [[3, 0], [0, 2]], possible: true,
          takeaway: 'Stretching a point on an axis keeps it on that axis, so V is closed under scalar multiplication. But adding a point from each axis lands off both axes, so V is NOT a subspace.'
        },
        {
          id: 6, dim: 2, title: 'Level 6: Quadrants I and III',
          prompt: 'W holds the points where x and y are both ≥ 0 or both ≤ 0. Stretching by a negative λ stays inside! How else can you escape?',
          setType: 'double_cone', setName: 'W', ruleText: 'W = { (x, y) : both x, y ≥ 0 or both x, y ≤ 0 }',
          initVecs: [[4, 1], [-1, -4]], possible: true,
          takeaway: 'W contains (0, 0) and is closed under scalar multiplication (a negative λ just flips Quadrant I into Quadrant III), but adding a vector from each quadrant can leave W, so W is NOT a subspace.'
        },
        {
          id: 7, dim: 2, title: 'Level 7: A Curved Set',
          prompt: 'V is the curve y = 0.25x². Pick u, v on the curve, then stretch or add them to jump off it!',
          setType: 'parabola', setName: 'V', ruleText: 'V = { (x, y) : y = 0.25x² }',
          initVecs: [[2, 1], [-2, 1]], possible: true,
          takeaway: 'Curved sets are never subspaces: stretching or adding points on a curve lands off the curve.'
        },
        {
          id: 8, dim: 2, title: 'Level 8: Every (α, α + β)',
          prompt: 'V = { (α, α + β) : α, β ∈ ℝ }. Notice it shades the whole plane! Pick u, v and try to escape, or declare it impossible.',
          setType: 'full_r2', setName: 'V', ruleText: 'V = { (α, α + β) : α, β ∈ ℝ }',
          initVecs: [[2, 1], [-1, 2]], possible: false,
          mcQuestion: 'Why can you never escape V = { (α, α + β) : α, β ∈ ℝ }?',
          mcOptions: [
            { text: 'Any point (x, y) can be written with α = x and β = y - x, so V is all of ℝ². Stretching and adding can never leave ℝ².', correct: true },
            { text: 'You can only escape V by stretching with λ = 0.', correct: false },
            { text: 'Only collinear vectors can escape V.', correct: false }
          ],
          takeaway: 'V contains the zero vector, is closed under scalar multiplication, and is closed under addition, so V is a subspace (here it is the entire ambient space ℝ²).'
        },
        {
          id: 9, dim: 3, title: 'Level 9: Upper Half of 3D Space',
          prompt: 'In 3D: V is every point on or above the floor (z ≥ 0). Move u, v using the xy-floor and z-head handles, then escape!',
          setType: 'half_space_3d', setName: 'V', ruleText: 'V = { (x, y, z) : z ≥ 0 }',
          initVecs: [[2, 1, 2], [-2, 1, 1]], possible: true,
          takeaway: 'Just like Q in 2D, the upper half of 3D space contains 0 and is closed under addition, but a negative λ pushes z below 0, so it is NOT a subspace.'
        },
        {
          id: 10, dim: 3, title: 'Level 10: A Plane Through the Origin in 3D',
          prompt: 'In 3D: V is the tilted plane z = 0.5x + 0.5y through (0, 0, 0). Place u, v on the plane and test whether you can escape!',
          setType: 'plane_origin_3d', setName: 'V', ruleText: 'V = { (x, y, z) : z = 0.5x + 0.5y }',
          initVecs: [[2, 0, 1], [0, 2, 1]], possible: false,
          mcQuestion: 'Why can no combination of u and v ever leave the plane z = 0.5x + 0.5y?',
          mcOptions: [
            { text: 'The plane passes through (0, 0, 0), and stretching or adding points on a flat plane through the origin always stays on the plane. It is a subspace!', correct: true },
