          prompt: 'v1 = (2, 0, 1), v2 = (0, 2, 1), and v3 = (-2, -2, -2) all lie on the same plane. Chain them back to (0, 0, 0)!',
          vecs: [[2, 0, 1], [0, 2, 1], [-2, -2, -2]], possible: true,
