          prompt: 'v1 = (2, 0, 0), v2 = (0, 2, 0), and v3 = (1, 1, 2) pokes up out of the floor. Can you loop back to (0, 0, 0)?',
          vecs: [[2, 0, 0], [0, 2, 0], [1, 1, 2]], possible: false,
          mcQuestion: 'Why can these 3 vectors NEVER loop back to (0, 0, 0) with a non-zero λ?',
          mcOptions: [
            { text: 'Only v3 has a z-component, so getting z = 0 forces λ3 = 0, which then forces λ1 = λ2 = 0. They are linearly independent.', correct: true },
            { text: '3 vectors in 3D are never dependent.', correct: false },
            { text: 'v1 and v2 are perpendicular.', correct: false }
          ],
          takeaway: 'm = 3 vectors in n = 3 dimensions MAY be independent (m ≤ n), but you have to check. Here d = 3, so they create all of ℝ³.'
        },
        {
          id: 9, dim: 3, title: 'Level 9: A Hidden Combination',
          prompt: 'No two of v1 = (1, 0, 1), v2 = (0, 1, 1), v3 = (2, -1, 1) are collinear. Can you still stretch and chain them from (0, 0, 0) back to (0, 0, 0)? Rotate the view to check your chain!',
          vecs: [[1, 0, 1], [0, 1, 1], [2, -1, 1]], possible: true,
          takeaway: 'No pair is collinear, yet one vector is secretly a combination of the other two. Only d = 2 of them are linearly independent, so they create a 2-dimensional subspace (a plane).'
        },
        {
          id: 10, dim: 3, title: 'Level 10: Four Vectors in 3D (m > n)',
          prompt: 'v1 = (2, 0, 0), v2 = (0, 2, 0), v3 = (0, 0, 2), v4 = (-2, -2, -2). Chain all 4 tip-to-tail from (0, 0, 0) back to (0, 0, 0)!',
          vecs: [[2, 0, 0], [0, 2, 0], [0, 0, 2], [-2, -2, -2]], possible: true,
          takeaway: 'With m = 4 vectors in n = 3 dimensions (m > n), the collection MUST be linearly dependent.'
        }
      ]
    };

    const COLORS = ['#2563eb', '#dc2626', '#16a34a', '#9333ea'];
    const NAMES  = ['v1', 'v2', 'v3', 'v4'];
    const P2_NAMES = ['u', 'v'];

    let activePanel = 'panel1';
    let activeIdx   = { panel1: 0, panel2: 0, panel3: 0 };
    let completed   = { panel1: {}, panel2: {}, panel3: {} };

    // State of current level
    let state = {
      phase: 1,       // Panel 2: 1 = Pick inside W, 2 = Scale & Combine to escape
      vecs: [],       // Each item: { base: [x,y,(z)], c: 1, tail: [x,y,(z)], freeTip: [x,y,(z)] }
      dragging: null, // { idx, part: 'head'|'xy'|'shaft'|'xy_shaft'|'zero_ring', startMouse, startVal }
      hover: null,
      camYaw: -2.3,
      camPitch: 0.35
    };
    const DEFAULT_YAW = -2.3, DEFAULT_PITCH = 0.35;  // textbook view: +x toward you, +y right, +z up
    const VIEW = { lim: 4.5 };   // max |coordinate| a vector tail/tip may be dragged to (2D)
    let SCALE_2D = 54;           // pixels per unit in 2D (recomputed per level, changed by zoom)
    let SCALE_3D = 38;           // pixels per unit in 3D (changed by zoom)
    const DEFAULT_SCALE_3D = 38;   // sized so the whole bounding box fits at the default angle

    // Zoom in/out around the origin. factor > 1 zooms in.
    function zoomView(factor) {
      const lvl = currentLevel();
      if (lvl.dim === 3) {
        SCALE_3D = Math.max(18, Math.min(110, SCALE_3D * factor));
      } else {
        SCALE_2D = Math.max(12, Math.min(110, SCALE_2D * factor));
        syncDragLimit();
      }
      drawCanvas();
    }
    // 2D drag limit = whatever is visible on screen (never less than the level needs)
    function syncDragLimit() {
      const lvl = currentLevel();
      VIEW.lim = Math.max(lvl.extent || 4.5, 280 / SCALE_2D - 0.4);
    }
    function resetView() {
      const lvl = currentLevel();
      SCALE_2D = Math.min(54, 270 / ((lvl.extent || 4.5) + 0.6));
      SCALE_3D = DEFAULT_SCALE_3D;
      state.camYaw = DEFAULT_YAW;
      state.camPitch = DEFAULT_PITCH;
      syncDragLimit();
      drawCanvas();
    }

    function mountWorkspace(panelName) {
      const mount = document.getElementById('mount-' + panelName);
      if (!mount) return;
      // Only ONE copy of the workspace may exist at a time (all panels share element IDs).
      // Clear the other panels first so getElementById() targets the visible panel.
      ['panel1', 'panel2', 'panel3'].forEach(p => {
        const other = document.getElementById('mount-' + p);
        if (other && p !== panelName) other.innerHTML = '';
      });
      mount.innerHTML = workspaceHTML;
      fitCanvasWidth();
      bindEvents();
      loadLevel(panelName, activeIdx[panelName]);
    }

    // Match the canvas drawing width to its on-screen width so nothing is stretched
    function fitCanvasWidth() {
      const canvas = document.getElementById('vecCanvas');
      if (!canvas) return;
      const w = Math.round(canvas.getBoundingClientRect().width);
      if (w > 200 && w !== canvas.width) canvas.width = w;
    }
    window.addEventListener('resize', () => { fitCanvasWidth(); drawCanvas(); });

    function currentLevel() {
      return LEVELS[activePanel][activeIdx[activePanel]];
    }

    function loadLevel(panelName, idx) {
      activePanel = panelName;
      activeIdx[panelName] = idx;
      const lvl = currentLevel();

      state.phase = (panelName === 'panel2') ? 1 : 2;
      state.dragging = null;
      state.hover = null;
      state.vecs = [];
      state.camYaw = DEFAULT_YAW;
      state.camPitch = DEFAULT_PITCH;
      // 2D view: zoom out on levels whose targets / chains need more room
      SCALE_2D = Math.min(54, 270 / ((lvl.extent || 4.5) + 0.6));
      SCALE_3D = DEFAULT_SCALE_3D;
      syncDragLimit();

      if (panelName === 'panel2') {
        lvl.initVecs.forEach((v) => {
          const coords = lvl.dim === 3 ? [v[0], v[1], v[2]] : [v[0], v[1], 0];
          state.vecs.push({
            base: [...coords],
            freeTip: [...coords],
            c: 1.0,
            tail: [0, 0, 0]
          });
        });
      } else {
        lvl.vecs.forEach((v) => {
          const coords = lvl.dim === 3 ? [v[0], v[1], v[2]] : [v[0], v[1], 0];
          state.vecs.push({
            base: [...coords],
            freeTip: [...coords],
            c: 1.0,
            tail: [0, 0, 0]
          });
        });
      }

      renderLevelBar();
      updateUI();
      hidePopup();
      drawCanvas();
    }

    function renderLevelBar() {
      const bar = document.getElementById('levelBar');
      if (!bar) return;
      bar.innerHTML = '';
      LEVELS[activePanel].forEach((lvl, i) => {
        const btn = document.createElement('button');
        const isDone = !!completed[activePanel][lvl.id];
        const isAct  = (i === activeIdx[activePanel]);
        btn.className = 'lvl-btn' + (isAct ? ' active' : '') + (isDone ? ' done' : '');
        btn.innerHTML = `<span>L${lvl.id}${isDone ? ' ✓' : ''}</span><span class='dim-tag'>${lvl.dim}D</span>`;
        btn.onclick = () => loadLevel(activePanel, i);
        bar.appendChild(btn);
      });
    }

    // =========================================================================
    // SET MEMBERSHIP & GEOMETRIC EVALUATION
    // =========================================================================
    function isInSetW(pt, lvl) {
      const x = pt[0], y = pt[1], z = pt[2] || 0;
      const tol = 0.22;
      switch (lvl.setType) {
        case 'line_shifted':   return Math.abs(y - (0.5 * x + 2)) <= tol;
        case 'line_origin':    return Math.abs(y - (-0.5 * x)) <= tol;
        case 'segment':        return Math.abs(y - x) <= tol && Math.abs(x) <= 2.0 + tol && Math.abs(y) <= 2.0 + tol;
        case 'quad1':          return x >= -0.05 && y >= -0.05;
        case 'axes_union':     return Math.abs(x) <= tol || Math.abs(y) <= tol;
        case 'double_cone':    return (x * y) >= -0.08;
        case 'parabola':       return Math.abs(y - 0.25 * x * x) <= tol;
        case 'full_r2':        return true;
        case 'half_space_3d':  return z >= -0.05;
        case 'plane_origin_3d':return Math.abs(z - (0.5 * x + 0.5 * y)) <= tol;
      }
      return true;
    }

    // Snap slightly onto thin algebraic curves in Phase 1 when within valid tolerance
    function snapToSetIfClose(pt, lvl) {
      let [x, y, z] = pt;
      const snapTol = 0.32;
      switch (lvl.setType) {
        case 'line_shifted':
          if (Math.abs(y - (0.5 * x + 2)) <= snapTol) y = 0.5 * x + 2;
          break;
        case 'line_origin':
          if (Math.abs(y - (-0.5 * x)) <= snapTol) y = -0.5 * x;
          break;
        case 'segment':
          if (Math.abs(y - x) <= snapTol && Math.abs(x) <= 2.15) {
            x = Math.max(-2, Math.min(2, Math.round(x * 4) / 4));
            y = x;
          }
          break;
        case 'axes_union':
          if (Math.abs(x) <= snapTol) x = 0;
          else if (Math.abs(y) <= snapTol) y = 0;
          break;
        case 'parabola':
          if (Math.abs(y - 0.25 * x * x) <= snapTol) {
            x = Math.round(x * 2) / 2;
            y = 0.25 * x * x;
          }
          break;
        case 'plane_origin_3d':
          if (Math.abs(z - (0.5 * x + 0.5 * y)) <= snapTol) {
            z = 0.5 * x + 0.5 * y;
          }
          break;
      }
      return [x, y, z];
    }

    function getVecDisp(v) {
      if (activePanel === 'panel2' && state.phase === 1) {
        return [...v.freeTip];
      }
      return [v.base[0] * v.c, v.base[1] * v.c, v.base[2] * v.c];
    }

    function getVecTip(v) {
      const d = getVecDisp(v);
      return [v.tail[0] + d[0], v.tail[1] + d[1], v.tail[2] + d[2]];
    }

    function dist3(a, b) {
      return Math.hypot(a[0] - b[0], a[1] - b[1], (a[2] || 0) - (b[2] || 0));
    }

    function isZeroBase(v) {
      return Math.hypot(v.base[0], v.base[1], v.base[2]) < 1e-4;
    }

    // Finds longest/valid tip-to-tail chains starting at Origin (0,0,0)
    function evaluateChains() {
      const n = state.vecs.length;
      const activeIndices = [];
      state.vecs.forEach((v, i) => {
        if (!isZeroBase(v) && Math.abs(v.c) >= 0.08) activeIndices.push(i);
      });

      // Explore all valid tip-to-tail paths starting from (0,0,0)
      let validPaths = [];
      function dfs(currPt, usedMask, path) {
        if (path.length > 0) {
          validPaths.push({ tip: currPt, path: [...path], count: path.length });
        }
        for (let i = 0; i < n; i++) {
          if (usedMask & (1 << i)) continue;
          const v = state.vecs[i];
          if (isZeroBase(v) || Math.abs(v.c) < 0.08) continue;
          if (dist3(v.tail, currPt) <= 0.28) {
            dfs(getVecTip(v), usedMask | (1 << i), [...path, i]);
          }
        }
      }
      dfs([0, 0, 0], 0, []);
      return { validPaths, activeCount: activeIndices.length };
    }

    function evaluateStatus() {
      const lvl = currentLevel();
      const chains = evaluateChains();

      if (activePanel === 'panel1') {
        const t = lvl.dim === 3 ? lvl.target : [lvl.target[0], lvl.target[1], 0];
        // Check if any valid chain of all active vectors hits target
        const fullHit = chains.validPaths.find(
          p => p.count === chains.activeCount && dist3(p.tip, t) <= 0.28
        );
        if (fullHit) {
          return { ok: true, pillClass: 'pill-success', msg: 'Target reached! Your stretched-and-combined vectors land on T. Click \"Check Solution\"!' };
        }
        // Check if algebraic sum hits T but vectors aren't chained tip-to-tail yet
        let sum = [0, 0, 0];
        state.vecs.forEach(v => {
          const d = getVecDisp(v);
          sum[0] += d[0]; sum[1] += d[1]; sum[2] += d[2];
        });
        if (dist3(sum, t) <= 0.28) {
          return { ok: false, pillClass: 'pill-warning', msg: 'Your λ values are right! Now drag the vector shafts to chain them tip-to-tail starting from the origin (0, 0).' };
        }
        return { ok: false, pillClass: 'pill-neutral', msg: 'Stretch each vector by dragging its head (this sets λ), then drag the shafts to chain them tip-to-tail from (0, 0) to T.' };
      }

      if (activePanel === 'panel2') {
        if (state.phase === 1) {
          let outsideIdx = -1;
          let zeroIdx = -1;
          state.vecs.forEach((v, i) => {
            if (!isInSetW(v.freeTip, lvl)) outsideIdx = i;
            if (Math.hypot(v.freeTip[0], v.freeTip[1], v.freeTip[2]) < 0.2) zeroIdx = i;
          });
          if (outsideIdx !== -1) {
            return {
              ok: false, canPhase2: false, pillClass: 'pill-danger',
              msg: `Vector ${P2_NAMES[outsideIdx]} is OUTSIDE ${lvl.setName}! Move its head back inside ${lvl.setName} to unlock Phase 2.`
            };
          }
          if (zeroIdx !== -1) {
            return {
              ok: false, canPhase2: false, pillClass: 'pill-danger',
              msg: `Keep ${P2_NAMES[zeroIdx]} non-zero so you have two different vectors in ${lvl.setName} to test!`
            };
          }
          return {
            ok: false, canPhase2: true, pillClass: 'pill-success',
            msg: `Both u and v are in ${lvl.setName}! Click \"Lock Vectors in Set & Enter Phase 2\" below.`
          };
        } else {
          // Phase 2: Check if any chained path from origin lands OUTSIDE the set.
          // A vector stretched by λ = 0 is the zero vector; that escapes if 0 is not in the set.
          const zeroIdx = state.vecs.findIndex(v => Math.abs(v.c) < 0.08);
          if (zeroIdx !== -1 && !isInSetW([0, 0, 0], lvl)) {
            return {
              ok: true, escapedTip: [0, 0, 0], via: 'zero', zeroIdx: zeroIdx, pillClass: 'pill-success',
              msg: `ESCAPED ${lvl.setName}! 0·${P2_NAMES[zeroIdx]} is the zero vector, which is NOT in ${lvl.setName}. Click \"Check Solution\".`
            };
          }
          for (let p of chains.validPaths) {
            if (!isInSetW(p.tip, lvl)) {
              return {
                ok: true, escapedTip: p.tip, via: 'path', path: p.path, pillClass: 'pill-success',
                msg: `ESCAPED ${lvl.setName}! The tip (${fmtPt(p.tip, lvl.dim)}) lands OUTSIDE ${lvl.setName}. Click \"Check Solution\".`
              };
            }
          }
          return {
            ok: false, pillClass: 'pill-neutral',
            msg: `Phase 2: Stretch u and v (change λ) or chain them tip-to-tail from (0, 0) to land a tip OUTSIDE ${lvl.setName}!`
          };
        }
      }

      if (activePanel === 'panel3') {
        const maxScalar = Math.max(...state.vecs.map(v => Math.abs(v.c)));

        if (maxScalar < 0.45) {
          return {
            ok: false, trivial: true, pillClass: 'pill-danger',
            msg: 'Setting every λ = 0 does not count. Nice try! At least one λ must be non-zero.'
          };
        }
        const loopHit = chains.validPaths.find(
          p => p.count === chains.activeCount && chains.activeCount > 0 && dist3(p.tip, [0, 0, 0]) <= 0.28
        );
        if (loopHit) {
          return {
            ok: true, pillClass: 'pill-success',
            msg: 'Back at the origin! Your chain produces the zero vector with at least one non-zero λ. Click \"Check Solution\"!'
          };
        }
        // Check if algebraic sum is 0 but not chained tip-to-tail
        let sum = [0, 0, 0];
        state.vecs.forEach(v => {
          const d = getVecDisp(v);
          sum[0] += d[0]; sum[1] += d[1]; sum[2] += d[2];
        });
        if (dist3(sum, [0, 0, 0]) <= 0.28 && chains.activeCount > 0) {
          return {
            ok: false, pillClass: 'pill-warning',
            msg: 'Your λ values produce the zero vector! Now drag the shafts to chain every non-zero vector tip-to-tail from (0, 0) back to (0, 0).'
          };
        }
        return {
          ok: false, pillClass: 'pill-neutral',
          msg: 'Stretch the vectors (set each λ) and chain them tip-to-tail so the path starts at (0, 0) and ends back at (0, 0).'
        };
      }
    }

    function fmtNum(n) {
      const r = Math.round(n * 100) / 100;
      return Object.is(r, -0) ? '0' : r.toString();
    }
    function fmtPt(pt, dim) {
      return dim === 3
        ? `${fmtNum(pt[0])}, ${fmtNum(pt[1])}, ${fmtNum(pt[2])}`
        : `${fmtNum(pt[0])}, ${fmtNum(pt[1])}`;
    }

    // =========================================================================
    // ADAPTIVE EXPLANATIONS (built from the student's actual λ values)
    // =========================================================================
    function vecName(i) { return (activePanel === 'panel2') ? P2_NAMES[i] : NAMES[i]; }
    function scaled(i) {
      const v = state.vecs[i];
      return [v.base[0] * v.c, v.base[1] * v.c, v.base[2] * v.c];
    }
    // e.g. idxs [0,1] with λ = (2, -3)  ->  '2·v1 - 3·v2'
    function comboStr(idxs, lams, names) {
      return idxs.map((i, k) => {
        const l = lams[k];
        const term = `${fmtNum(Math.abs(l))}·${names[k]}`;
        if (k === 0) return (l < 0 ? '-' : '') + term;
        return (l < 0 ? ' - ' : ' + ') + term;
      }).join('');
    }
    function zeroStr(dim) { return dim === 3 ? '(0, 0, 0)' : '(0, 0)'; }

    function explainSolution(lvl, st) {
      const dim = lvl.dim;
      const all = state.vecs.map((v, i) => i);
      const lamsOf = idxs => idxs.map(i => state.vecs[i].c);
      const namesOf = idxs => idxs.map(i => vecName(i));
      let html = '';

      if (activePanel === 'panel1') {
        const t = dim === 3 ? lvl.target : [lvl.target[0], lvl.target[1], 0];
        html = `<strong>Your solution:</strong> ${comboStr(all, lamsOf(all), namesOf(all))} = (${fmtPt(t, dim)}) = T.<br>`;
        const zeros = all.filter(i => Math.abs(state.vecs[i].c) < 0.08);
        if (zeros.length > 0 && zeros.length < all.length) {
          html += `You did not even need ${zeros.map(vecName).join(' and ')} (λ = 0). `;
        }
        html += `So T is a point you can reach by stretching and combining these vectors: it is in their subspace.`;
      }

      else if (activePanel === 'panel2') {
        const S = lvl.setName;
        if (st.via === 'zero') {
          const n = P2_NAMES[st.zeroIdx];
          html = `<strong>Your move:</strong> you stretched ${n} by λ = 0, and 0·${n} = ${zeroStr(dim)} is the zero vector. ` +
                 `The zero vector is NOT in ${S}, so ${S} fails condition 1 (it must contain the zero vector).`;
        } else {
          const p = st.path;
          const tip = fmtPt(st.escapedTip, dim);
          if (p.length === 1) {
            const i = p[0], l = state.vecs[i].c;
            html = `<strong>Your move:</strong> you stretched ${vecName(i)} by λ = ${fmtNum(l)}: ` +
                   `${fmtNum(l)}·${vecName(i)} = (${tip}), which is NOT in ${S}. ` +
                   `So ${S} is NOT closed under scalar multiplication.`;
          } else {
            const combo = comboStr(p, lamsOf(p), namesOf(p));
            const outside = p.filter(i => !isInSetW(scaled(i), lvl));
            const allOne = p.every(i => Math.abs(state.vecs[i].c - 1) < 0.01);
            if (outside.length > 0) {
              const i = outside[0];
              html = `<strong>Your move:</strong> ${combo} = (${tip}) is NOT in ${S}. In fact, the stretched vector ` +
                     `${fmtNum(state.vecs[i].c)}·${vecName(i)} = (${fmtPt(scaled(i), dim)}) is already outside ${S} before you add anything, ` +
                     `so ${S} is NOT closed under scalar multiplication.`;
            } else if (allOne) {
              html = `<strong>Your move:</strong> you added the vectors: ${namesOf(p).join(' + ')} = (${tip}). ` +
                     `Both are in ${S}, but their sum is NOT, so ${S} is NOT closed under addition.`;
            } else {
              html = `<strong>Your move:</strong> ` +
                     p.map(i => `${fmtNum(state.vecs[i].c)}·${vecName(i)} = (${fmtPt(scaled(i), dim)})`).join(' and ') +
                     ` are both still in ${S}, but their sum ${combo} = (${tip}) is NOT. So ${S} is NOT closed under addition.`;
            }
          }
        }
      }

      else if (activePanel === 'panel3') {
        const lams = lamsOf(all);
        html = `<strong>Your solution:</strong> ${comboStr(all, lams, namesOf(all))} = ${zeroStr(dim)}, with at least one λ non-zero.`;
        const act = all.filter(i => Math.abs(state.vecs[i].c) >= 0.08);
        const zeros = all.filter(i => Math.abs(state.vecs[i].c) < 0.08);
        if (act.length >= 2) {
          // Solve for the last active vector in terms of the others
          const k = act[act.length - 1];
          const others = act.filter(i => i !== k);
          const coefs = others.map(i => -state.vecs[i].c / state.vecs[k].c);
          html += `<br>Rearranging: ${vecName(k)} = ${comboStr(others, coefs, namesOf(others))}, so ${vecName(k)} is a linear combination of the others`;
          html += others.length === 1 ? ` (the two vectors are collinear).` : `.`;
        }
        if (zeros.length > 0) {
          html += `<br>You used λ = 0 on ${zeros.map(vecName).join(' and ')}. That is allowed: only <em>at least one</em> λ has to be non-zero.`;
        }
        html += `<br>Producing the zero vector this way means the collection is <strong>linearly dependent</strong>.`;
      }

      return html + (lvl.takeaway ? `<br><span style='display:block;margin-top:6px;'>${lvl.takeaway}</span>` : '');
    }

    function updateUI() {
      const lvl = currentLevel();
      const st  = evaluateStatus();

      document.getElementById('lvlTitle').textContent = lvl.title;
      document.getElementById('lvlPrompt').textContent = lvl.prompt;

      const badgeWrap = document.getElementById('phaseBadgeWrap');
      const btnPhase  = document.getElementById('btnPhase');
      if (activePanel === 'panel2') {
        if (state.phase === 1) {
          badgeWrap.innerHTML = `<span class='phase-badge phase-1'>Phase 1 of 2: Pick Vectors Inside ${lvl.setName}</span>`;
          btnPhase.style.display = 'block';
          btnPhase.disabled = !st.canPhase2;
          btnPhase.textContent = 'Lock Vectors in Set & Enter Phase 2 →';
        } else {
          badgeWrap.innerHTML = `<span class='phase-badge phase-2'>Phase 2 of 2: Stretch & Add to Escape ${lvl.setName}</span>`;
          btnPhase.style.display = 'block';
          btnPhase.disabled = false;
          btnPhase.textContent = '← Return to Phase 1 (Pick Different Vectors)';
        }
      } else {
        badgeWrap.innerHTML = '';
        btnPhase.style.display = 'none';
      }

      const pill = document.getElementById('statusPill');
      pill.className = 'status-pill ' + st.pillClass;
      pill.textContent = st.msg;

      const btnImposs = document.getElementById('btnImposs');
      if (activePanel === 'panel1') btnImposs.textContent = 'Declare Impossible (T Is Not Reachable)';
      else if (activePanel === 'panel2') btnImposs.textContent = 'Declare Impossible to Escape (It Is a Subspace)';
      else btnImposs.textContent = 'Declare Impossible (Linearly Independent)';

      // Readout box
      const ro = document.getElementById('vecReadout');
      let html = '';
      if (activePanel === 'panel2' && lvl.ruleText) {
        html += `<div class='vec-row'><strong>Set Rule:</strong> <span>${lvl.ruleText}</span></div>`;
      }
      if (activePanel === 'panel1') {
        html += `<div class='vec-row'><strong>Target T:</strong> <span>(${fmtPt(lvl.target, lvl.dim)})</span></div>`;
      }
      state.vecs.forEach((v, i) => {
        const name = (activePanel === 'panel2') ? P2_NAMES[i] : NAMES[i];
        const col  = COLORS[i % COLORS.length];
        const tip  = getVecTip(v);
        const disp = getVecDisp(v);
        if (activePanel === 'panel2' && state.phase === 1) {
          const inside = isInSetW(v.freeTip, lvl);
          html += `<div class='vec-row'>
            <span style='color:${col};font-weight:700;'>${name} = (${fmtPt(v.freeTip, lvl.dim)})</span>
            <span style='color:${inside ? \"#16a34a\" : \"#dc2626\"};font-weight:700;'>${inside ? '∈ ' + lvl.setName + ' (Inside)' : '∉ ' + lvl.setName + ' (Outside!)'}</span>
                            </div>`;
                            } else {
                              html += `<div class='vec-row'>
                                <span style='color:${col};font-weight:700;'>λ${i+1} = ${fmtNum(v.c)} |${name}: (${fmtPt(disp, lvl.dim)})</span>
                                  <span class='text-muted'>Tip: (${fmtPt(tip, lvl.dim)})</span>
                                    </div>`;
                            }
});
ro.innerHTML = html;

// Help strip instructions
const help = document.getElementById('helpStrip');
if (lvl.dim === 2) {
  if (activePanel === 'panel2' && state.phase === 1) {
    help.innerHTML = `<strong>2D Controls (Phase 1):</strong> Drag the colored <strong>vector heads</strong> anywhere inside the shaded/blue set <em>${lvl.setName}</em>. <strong>Scroll or use + / − to zoom.</strong>`;
  } else {
    help.innerHTML = `<strong>2D Controls:</strong> Drag a vector's <strong>arrowhead</strong> along its dashed line to stretch it by a scalar <em>λ</em> (past the tail flips it, making λ negative). Drag its <strong>shaft</strong> to move it and snap it <strong>tip-to-tail</strong> starting from the origin! <strong>Scroll or use + / − to zoom.</strong>`;
  }
} else {
  if (activePanel === 'panel2' && state.phase === 1) {
    help.innerHTML = `<strong>3D Controls (Phase 1):</strong> Drag the hollow <strong>floor ring</strong> to move <em>(x, y)</em> along the floor; drag the <strong>arrowhead</strong> up or down to change <em>z</em>. <strong>Drag any empty spot to rotate the view; scroll or use + / − to zoom.</strong>`;
  } else {
    help.innerHTML = `<strong>3D Controls:</strong> Drag a vector's <strong>arrowhead</strong> (or its hollow floor ring) along its line to stretch it by <em>λ</em>. Drag its <strong>shaft</strong> and drop the tail on the origin or another vector's tip to chain <strong>tip-to-tail</strong> (it snaps into place). <strong>Drag any empty spot to rotate the view; scroll or use + / − to zoom.</strong>`;
  }
}
}

function showPopup(type, htmlContent) {
  const box = document.getElementById('popupBox');
  box.className = 'popup-box ' + type;
  box.innerHTML = htmlContent;
  box.style.display = 'block';
}
function hidePopup() {
  const box = document.getElementById('popupBox');
  if (box) box.style.display = 'none';
}

function bindEvents() {
  document.getElementById('btnPhase').onclick = () => {
    const lvl = currentLevel();
    if (state.phase === 1) {
      const st = evaluateStatus();
      if (!st.canPhase2) return;
      // Lock current freeTip as base vectors for Phase 2
      state.vecs.forEach(v => {
        v.base = [...v.freeTip];
        v.c = 1.0;
        v.tail = [0, 0, 0];
      });
      state.phase = 2;
    } else {
      state.phase = 1;
      state.vecs.forEach(v => {
        v.freeTip = [...v.base];
        v.c = 1.0;
        v.tail = [0, 0, 0];
      });
    }
    hidePopup();
    updateUI();
    drawCanvas();
  };

  document.getElementById('btnCheck').onclick = () => {
    const lvl = currentLevel();
    const st  = evaluateStatus();
    if (!lvl.possible) {
      showPopup('popup-red', `<strong>Keep looking!</strong> Your current setup hasn't solved the goal. (If you suspect no valid solution exists, test the <em>Declare Impossible</em> button!)`);
      return;
    }
    if (st.trivial) {
      showPopup('popup-red', `<strong>Not a valid solution. Nice try!</strong> Setting every λ = 0 always gives the zero vector, so it proves nothing. At least one λ must be non-zero.`);
      return;
    }
    if (st.ok) {
      completed[activePanel][lvl.id] = true;
      renderLevelBar();
      showPopup('popup-green', `<strong>✓ Level ${lvl.id} Cleared!</strong><br>${explainSolution(lvl, st)}`);
    } else {
      showPopup('popup-red', `<strong>Not quite yet!</strong> ${st.msg}`);
    }
  };

  document.getElementById('btnImposs').onclick = () => {
    const lvl = currentLevel();
    if (lvl.possible) {
      showPopup('popup-red', `<strong>Not impossible!</strong> A valid geometric solution exists on this level — keep trying!`);
      return;
    }
    // Build multiple-choice verification card
    let html = `<strong>${lvl.mcQuestion || 'Why is this level impossible?'}</strong><div style='margin-top:6px;'>`;
    // Shuffle answer order (Fisher-Yates) so the correct answer is not always first
    const order = lvl.mcOptions.map((o, i) => i);
    for (let i = order.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [order[i], order[j]] = [order[j], order[i]];
    }
    order.forEach(idx => {
      html += `<button class='mc-option' data-idx='${idx}'>${lvl.mcOptions[idx].text}</button>`;
    });
    html += `</div><div id='mcFeedback' style='margin-top:8px;font-size:0.82rem;'></div>`;
    showPopup('popup-quiz', html);

    document.querySelectorAll('#popupBox .mc-option').forEach(btn => {
      btn.onclick = function() {
        const idx = parseInt(this.getAttribute('data-idx'));
        const chosen = lvl.mcOptions[idx];
        const fb = document.getElementById('mcFeedback');
        if (chosen.correct) {
          this.classList.add('correct');
          completed[activePanel][lvl.id] = true;
          renderLevelBar();
          fb.innerHTML = `<span style='color:#15803d;font-weight:700;'>✓ Spot on! ${lvl.takeaway}</span>`;
        } else {
          this.classList.add('wrong');
          fb.innerHTML = `<span style='color:#b91c1c;font-weight:600;'>Not quite — think about the dimension and geometry of the vectors. Try another choice!</span>`;
        }
      };
    });
  };

  document.getElementById('btnReset').onclick = () => {
    loadLevel(activePanel, activeIdx[activePanel]);
  };

  const canvas = document.getElementById('vecCanvas');
  canvas.addEventListener('pointerdown', onPointerDown);
  canvas.addEventListener('wheel', (e) => {
    e.preventDefault();
    zoomView(e.deltaY < 0 ? 1.12 : 1 / 1.12);
  }, { passive: false });
  document.getElementById('btnZoomIn').onclick = () => zoomView(1.25);
  document.getElementById('btnZoomOut').onclick = () => zoomView(1 / 1.25);
  document.getElementById('btnZoomReset').onclick = () => resetView();
  if (!window.__lec19PointerBound) {
    window.addEventListener('pointermove', onPointerMove);
    window.addEventListener('pointerup', onPointerUp);
    window.__lec19PointerBound = true;
  }
}

// =========================================================================
  // 2D & 3D PROJECTION ENGINE
// =========================================================================
  function project(pt, dim, W, H) {
    const cx = W / 2, cy = H / 2;
    if (dim === 2) {
      return [cx + pt[0] * SCALE_2D, cy - pt[1] * SCALE_2D];
    }
    // 3D orbit camera: yaw spins around the vertical z-axis, pitch tilts the floor toward you
    const x = pt[0], y = pt[1], z = pt[2] || 0;
    const cosY = Math.cos(state.camYaw), sinY = Math.sin(state.camYaw);
    const sinP = Math.sin(state.camPitch), cosP = Math.cos(state.camPitch);
    // Right-handed camera: screen-right = (cosY, -sinY, 0), into-screen (horizontal) f = (sinY, cosY, 0), up = z.
    // Tilting down by pitch makes far points (f > 0) appear HIGHER on screen.
    const f  = x * sinY + y * cosY;
    const sx = (x * cosY - y * sinY) * SCALE_3D;
    const sy = -(f * sinP + z * cosP) * SCALE_3D;
    return [cx + sx, cy + sy];
  }

  // How many z-units one screen pixel of vertical mouse motion represents
  function zPerPixel() {
    return 1 / (SCALE_3D * Math.max(0.15, Math.cos(state.camPitch)));
  }

  function unproject2D(sx, sy, W, H) {
    const cx = W / 2, cy = H / 2;
    return [(sx - cx) / SCALE_2D, (cy - sy) / SCALE_2D, 0];
  }

  // Inverse mapping from screen (sx, sy) to (x, y) on the horizontal plane z = fixedZ in 3D
  function unproject3DFloor(sx, sy, fixedZ, W, H) {
    const cx = W / 2, cy = H / 2;
    const sinP = Math.sin(state.camPitch), cosP = Math.cos(state.camPitch);
    const u = (sx - cx) / SCALE_3D;
    // Guard: when the floor is seen edge-on, avoid dividing by ~0
    const sinPs = Math.abs(sinP) < 0.06 ? (sinP < 0 ? -0.06 : 0.06) : sinP;
    const v = -((sy - cy) / SCALE_3D + fixedZ * cosP) / sinPs;
    const cosY = Math.cos(state.camYaw), sinY = Math.sin(state.camYaw);
    const x = u * cosY + v * sinY;
    const y = -u * sinY + v * cosY;
    return [x, y];
  }

  function distToSegment2D(p, a, b) {
    const l2 = (b[0] - a[0]) ** 2 + (b[1] - a[1]) ** 2;
    if (l2 === 0) return Math.hypot(p[0] - a[0], p[1] - a[1]);
    let t = ((p[0] - a[0]) * (b[0] - a[0]) + (p[1] - a[1]) * (b[1] - a[1])) / l2;
    t = Math.max(0.12, Math.min(0.85, t));
    return Math.hypot(p[0] - (a[0] + t * (b[0] - a[0])), p[1] - (a[1] + t * (b[1] - a[1])));
  }

  function getMousePos(e, canvas) {
    const rect = canvas.getBoundingClientRect();
    return [
      (e.clientX - rect.left) * (canvas.width / rect.width),
      (e.clientY - rect.top) * (canvas.height / rect.height)
    ];
  }

  function findHitHandle(mx, my, W, H) {
    const lvl = currentLevel();
    const dim = lvl.dim;
    const scaling = !(activePanel === 'panel2' && state.phase === 1);

    // 1. Handles (arrowheads, 3D floor rings, ghost handles): pick the NEAREST one under the mouse
    let best = null, bestD = Infinity;
    const consider = (d, radius, hit) => {
      if (d <= radius && d < bestD) { best = hit; bestD = d; }
    };
    for (let i = state.vecs.length - 1; i >= 0; i--) {
      const v = state.vecs[i];
      if (isZeroBase(v)) continue;
      const tail = v.tail;
      const tip  = getVecTip(v);
      const tipScr = project(tip, dim, W, H);
      const tailScr = project(tail, dim, W, H);
      // Short-looking vectors get a smaller head target so their shaft stays grabbable
      const headR = Math.max(10, Math.min(20, 0.3 * Math.hypot(tipScr[0] - tailScr[0], tipScr[1] - tailScr[1])));
      consider(Math.hypot(mx - tipScr[0], my - tipScr[1]), headR, { idx: i, part: 'head' });

      if (dim === 3) {
        const xyTipScr = project([tip[0], tip[1], 0], 3, W, H);
        // Slight penalty so the arrowhead wins when the two overlap
        consider(Math.hypot(mx - xyTipScr[0], my - xyTipScr[1]) + 4, 18, { idx: i, part: 'xy' });
      }
      // If vector is shrunk near λ = 0, a ghost handle lets you pull it back out
      if (scaling && Math.abs(v.c) < 0.15) {
        const g = project([tail[0] + v.base[0] * 0.45, tail[1] + v.base[1] * 0.45, tail[2] + v.base[2] * 0.45], dim, W, H);
        consider(Math.hypot(mx - g[0], my - g[1]), 16, { idx: i, part: 'head' });
      }
    }
    if (best) return best;

    // 2. Shafts for translation (tip-to-tail chaining)
    // (pick the NEAREST shaft: several vectors often share the origin as their tail)
    if (scaling) {
      const segDist = (p, a, b) => {
        const l2 = (b[0] - a[0]) ** 2 + (b[1] - a[1]) ** 2;
        if (l2 === 0) return Math.hypot(p[0] - a[0], p[1] - a[1]);
        const t = Math.max(0, Math.min(0.85, ((p[0] - a[0]) * (b[0] - a[0]) + (p[1] - a[1]) * (b[1] - a[1])) / l2));
        return Math.hypot(p[0] - (a[0] + t * (b[0] - a[0])), p[1] - (a[1] + t * (b[1] - a[1])));
      };
      for (let i = state.vecs.length - 1; i >= 0; i--) {
        const v = state.vecs[i];
        if (isZeroBase(v)) continue;
        const tail = v.tail;
        const tip  = getVecTip(v);
        consider(segDist([mx, my], project(tail, dim, W, H), project(tip, dim, W, H)), 14, { idx: i, part: 'shaft' });
        if (dim === 3) {
          const xyTailScr = project([tail[0], tail[1], 0], 3, W, H);
          const xyTipScr  = project([tip[0], tip[1], 0], 3, W, H);
          consider(segDist([mx, my], xyTailScr, xyTipScr) + 2, 13, { idx: i, part: 'xy_shaft' });
        }
      }
    }
    return best;
  }

    function onPointerDown(e) {
      const canvas = document.getElementById('vecCanvas');
      if (!canvas) return;
      const [mx, my] = getMousePos(e, canvas);
      const hit = findHitHandle(mx, my, canvas.width, canvas.height);
      if (hit) {
        const v = state.vecs[hit.idx];
        state.dragging = {
          idx: hit.idx,
          part: hit.part,
          startMouse: [mx, my],
          startC: v.c,
          startTail: [...v.tail],
          startFree: [...v.freeTip]
        };
      } else if (currentLevel().dim === 3) {
        // Dragging empty space in 3D rotates the camera (same direction wherever you grab)
        state.dragging = {
          part: 'camera',
          lastMouse: [mx, my]
        };
        canvas.style.cursor = 'grabbing';
      }
    }

    function onPointerMove(e) {
      const canvas = document.getElementById('vecCanvas');
      if (!canvas) return;
      const [mx, my] = getMousePos(e, canvas);
      const W = canvas.width, H = canvas.height;
      const lvl = currentLevel();
      const dim = lvl.dim;

      if (!state.dragging) {
        const h = findHitHandle(mx, my, W, H);
        canvas.style.cursor = h ? 'pointer' : (dim === 3 ? 'grab' : 'default');
        if (JSON.stringify(h) !== JSON.stringify(state.hover)) {
          state.hover = h;
          drawCanvas();
        }
        return;
      }

      const d = state.dragging;

      // Case 0: Rotating the 3D camera
      if (d.part === 'camera') {
        const dx = mx - d.lastMouse[0], dy = my - d.lastMouse[1];
        d.lastMouse = [mx, my];
        // Drag right -> the xy-plane turns counterclockwise (seen from above); drag left -> clockwise
        state.camYaw += dx * 0.01;
        state.camPitch = Math.max(-1.45, Math.min(1.45, state.camPitch + dy * 0.01));
        drawCanvas();
        return;
      }

      const v = state.vecs[d.idx];

      // Case 1: Panel 2 Phase 1 (Free vector placement in the set)
      if (activePanel === 'panel2' && state.phase === 1) {
        if (dim === 2 && d.part === 'head') {
          let [nx, ny] = unproject2D(mx, my, W, H);
          nx = Math.max(-VIEW.lim, Math.min(VIEW.lim, Math.round(nx * 4) / 4));
          ny = Math.max(-VIEW.lim, Math.min(VIEW.lim, Math.round(ny * 4) / 4));
          v.freeTip = snapToSetIfClose([nx, ny, 0], lvl);
        } else if (dim === 3) {
          if (d.part === 'xy') {
            // Moves ONLY (x, y) on the floor while keeping z locked
            let [nx, ny] = unproject3DFloor(mx, my, 0, W, H);
            nx = Math.max(-4, Math.min(4, Math.round(nx * 2) / 2));
            ny = Math.max(-4, Math.min(4, Math.round(ny * 2) / 2));
            v.freeTip = snapToSetIfClose([nx, ny, v.freeTip[2]], lvl);
          } else if (d.part === 'head') {
            // Moves ONLY up/down (z) while keeping (x, y) locked
            const dz = (d.startMouse[1] - my) * zPerPixel();
            let nz = Math.max(-4, Math.min(4, Math.round((d.startFree[2] + dz) * 2) / 2));
            v.freeTip = snapToSetIfClose([v.freeTip[0], v.freeTip[1], nz], lvl);
          }
        }
        updateUI();
        drawCanvas();
        return;
      }

      // Case 2: Stretching along the vector's own line (head) or its floor shadow (xy ring)
      if (d.part === 'head' || d.part === 'xy') {
        const useFloor = (dim === 3 && d.part === 'xy');
        const p0 = useFloor
          ? project([v.tail[0], v.tail[1], 0], 3, W, H)
          : project(v.tail, dim, W, H);
        const p1 = useFloor
          ? project([v.tail[0] + v.base[0], v.tail[1] + v.base[1], 0], 3, W, H)
          : project([v.tail[0] + v.base[0], v.tail[1] + v.base[1], v.tail[2] + v.base[2]], dim, W, H);
        const vx = p1[0] - p0[0], vy = p1[1] - p0[1];
        const len2 = vx * vx + vy * vy;
        if (len2 > 64) {
          const rawC = ((mx - p0[0]) * vx + (my - p0[1]) * vy) / len2;
          v.c = snapScalar(rawC);
        } else if (dim === 3 && Math.abs(v.base[2]) > 0.05) {
          // Vector points almost straight at the camera: fall back to vertical drag on z
          const dz = (d.startMouse[1] - my) * zPerPixel();
          v.c = snapScalar(d.startC + dz / v.base[2]);
        }
        updateUI();
        drawCanvas();
        return;
      }


  // Case 3: Translating vector tail (Tip-to-Tail Manual Dragging)
  if (d.part === 'shaft' || d.part === 'xy_shaft') {
    let candTail = [...v.tail];
    if (dim === 2) {
      const dx = (mx - d.startMouse[0]) / SCALE_2D;
      const dy = (d.startMouse[1] - my) / SCALE_2D;
      candTail = [
        Math.max(-VIEW.lim, Math.min(VIEW.lim, d.startTail[0] + dx)),
        Math.max(-VIEW.lim, Math.min(VIEW.lim, d.startTail[1] + dy)),
        0
      ];
    } else {
      if (d.part === 'xy_shaft') {
        // Moves tail in (x, y) across the xy-plane
        const startFl = unproject3DFloor(d.startMouse[0], d.startMouse[1], 0, W, H);
        const currFl  = unproject3DFloor(mx, my, 0, W, H);
        candTail = [
          Math.max(-4.5, Math.min(4.5, d.startTail[0] + (currFl[0] - startFl[0]))),
          Math.max(-4.5, Math.min(4.5, d.startTail[1] + (currFl[1] - startFl[1]))),
          d.startTail[2]
        ];
      } else {
        // 3D shaft: the vector follows the mouse at its current height;
        // drop its tail near (0,0,0) or another tip and it snaps there (including the height)
        const tailScr0 = project(d.startTail, 3, W, H);
        const fl = unproject3DFloor(tailScr0[0] + (mx - d.startMouse[0]), tailScr0[1] + (my - d.startMouse[1]), d.startTail[2], W, H);
        candTail = [
          Math.max(-4.5, Math.min(4.5, fl[0])),
          Math.max(-4.5, Math.min(4.5, fl[1])),
          d.startTail[2]
        ];
      }
    }

    // Magnetic Tip-to-Tail Snapping to Origin (0,0,0) or any other vector's Tip!
        const snapTargets = [[0, 0, 0]];
        state.vecs.forEach((other, j) => {
          if (j !== d.idx && (!isZeroBase(other) && Math.abs(other.c) >= 0.08)) {
            snapTargets.push(getVecTip(other));
          }
        });

        const candScr = project(candTail, dim, W, H);
        let snapped = null;
        for (let tPt of snapTargets) {
          const tScr = project(tPt, dim, W, H);
          if (dist3(candTail, tPt) <= 0.42 || Math.hypot(candScr[0] - tScr[0], candScr[1] - tScr[1]) <= 24) {
            snapped = [...tPt];
            break;
          }
        }

        if (snapped) {
          v.tail = snapped;
        } else {
          v.tail = [
            Math.round(candTail[0] * 4) / 4,
            Math.round(candTail[1] * 4) / 4,
            Math.round(candTail[2] * 4) / 4
          ];
        }
        updateUI();
        drawCanvas();
      }
    }

    function snapScalar(c) {
      c = Math.max(-3.5, Math.min(3.5, c));
      if (Math.abs(c) < 0.09) return 0;
      const q = Math.round(c * 4) / 4;
      if (Math.abs(c - q) < 0.09) return q;
      return Math.round(c * 20) / 20;
    }

    function onPointerUp() {
      if (state.dragging) {
        state.dragging = null;
        const canvas = document.getElementById('vecCanvas');
        if (canvas) canvas.style.cursor = '';
        drawCanvas();
      }
    }

    // =========================================================================
    // CANVAS RENDERING ENGINE
    // =========================================================================
    function drawArrow(ctx, p0, p1, color, width, dashed = false) {
      const dx = p1[0] - p0[0], dy = p1[1] - p0[1];
      const len = Math.hypot(dx, dy);
      ctx.save();
      ctx.strokeStyle = color;
      ctx.fillStyle = color;
      ctx.lineWidth = width;
      if (dashed) ctx.setLineDash([5, 5]);
      ctx.beginPath();
      ctx.moveTo(p0[0], p0[1]);
      ctx.lineTo(p1[0], p1[1]);
      ctx.stroke();
      ctx.setLineDash([]);

      if (len >= 6) {
        const ang = Math.atan2(dy, dx);
        const headLen = 12;
        ctx.beginPath();
        ctx.moveTo(p1[0], p1[1]);
        ctx.lineTo(p1[0] - headLen * Math.cos(ang - 0.35), p1[1] - headLen * Math.sin(ang - 0.35));
        ctx.lineTo(p1[0] - headLen * Math.cos(ang + 0.35), p1[1] - headLen * Math.sin(ang + 0.35));
        ctx.closePath();
        ctx.fill();
      }
      ctx.restore();
    }

    function drawSetOverlay(ctx, lvl, W, H) {
      ctx.save();
      const fillCol   = 'rgba(37, 99, 235, 0.11)';
      const strokeCol = 'rgba(37, 99, 235, 0.65)';
      ctx.fillStyle   = fillCol;
      ctx.strokeStyle = strokeCol;
      ctx.lineWidth   = 3;

      if (lvl.dim === 2) {
        const pOrigin = project([0, 0, 0], 2, W, H);
        switch (lvl.setType) {
          case 'line_shifted': {
            const a = project([-60, -28, 0], 2, W, H);
            const b = project([60, 32, 0], 2, W, H);
            ctx.beginPath(); ctx.moveTo(a[0], a[1]); ctx.lineTo(b[0], b[1]); ctx.stroke();
            break;
          }
          case 'line_origin': {
            const a = project([-60, 30, 0], 2, W, H);
            const b = project([60, -30, 0], 2, W, H);
            ctx.beginPath(); ctx.moveTo(a[0], a[1]); ctx.lineTo(b[0], b[1]); ctx.stroke();
            break;
          }
          case 'segment': {
            const a = project([-2, -2, 0], 2, W, H);
            const b = project([2, 2, 0], 2, W, H);
            ctx.lineWidth = 6;
            ctx.beginPath(); ctx.moveTo(a[0], a[1]); ctx.lineTo(b[0], b[1]); ctx.stroke();
            [a, b].forEach(p => {
              ctx.beginPath(); ctx.arc(p[0], p[1], 5, 0, Math.PI * 2); ctx.fillStyle = strokeCol; ctx.fill();
            });
            break;
          }
          case 'quad1': {
            ctx.fillRect(pOrigin[0], 0, W - pOrigin[0], pOrigin[1]);
            ctx.beginPath();
            ctx.moveTo(pOrigin[0], 0); ctx.lineTo(pOrigin[0], pOrigin[1]); ctx.lineTo(W, pOrigin[1]);
            ctx.stroke();
            break;
          }
          case 'axes_union': {
            ctx.lineWidth = 5;
            ctx.beginPath();
            ctx.moveTo(0, pOrigin[1]); ctx.lineTo(W, pOrigin[1]);
            ctx.moveTo(pOrigin[0], 0); ctx.lineTo(pOrigin[0], H);
            ctx.stroke();
            break;
          }
          case 'double_cone': {
            ctx.fillRect(pOrigin[0], 0, W - pOrigin[0], pOrigin[1]);
            ctx.fillRect(0, pOrigin[1], pOrigin[0], H - pOrigin[1]);
            break;
          }
          case 'parabola': {
            ctx.beginPath();
            const XM = (W / 2) / SCALE_2D + 1;
            for (let x = -XM; x <= XM; x += 0.1) {
              const p = project([x, 0.25 * x * x, 0], 2, W, H);
              if (x === -XM) ctx.moveTo(p[0], p[1]);
              else ctx.lineTo(p[0], p[1]);
            }
            ctx.stroke();
            break;
          }
          case 'full_r2': {
            ctx.fillRect(0, 0, W, H);
            break;
          }
        }
      } else {
        // 3D Wireframe Set Overlays
        if (lvl.setType === 'half_space_3d') {
          // Shade the whole region z >= 0 as a translucent box sitting on the floor
          const TOP = 4.2;
          const B = [[-4,-4,0], [4,-4,0], [4,4,0], [-4,4,0]];
          const T = B.map(p => [p[0], p[1], TOP]);
          const faces = [
            B, T,
            [B[0], B[1], T[1], T[0]], [B[1], B[2], T[2], T[1]],
            [B[2], B[3], T[3], T[2]], [B[3], B[0], T[0], T[3]]
          ];
          ctx.fillStyle = 'rgba(22, 163, 74, 0.06)';
          faces.forEach(f => {
            const s = f.map(p => project(p, 3, W, H));
            ctx.beginPath();
            s.forEach((c, i) => i === 0 ? ctx.moveTo(c[0], c[1]) : ctx.lineTo(c[0], c[1]));
            ctx.closePath(); ctx.fill();
          });
          // Floor boundary (z = 0) solid, upper edges dashed to show the region keeps going up
          ctx.strokeStyle = 'rgba(22, 163, 74, 0.75)'; ctx.lineWidth = 2;
          const bs = B.map(p => project(p, 3, W, H));
          ctx.beginPath(); bs.forEach((c, i) => i === 0 ? ctx.moveTo(c[0], c[1]) : ctx.lineTo(c[0], c[1])); ctx.closePath(); ctx.stroke();
          ctx.setLineDash([5, 5]); ctx.strokeStyle = 'rgba(22, 163, 74, 0.45)'; ctx.lineWidth = 1.3;
          const ts = T.map(p => project(p, 3, W, H));
          ctx.beginPath(); ts.forEach((c, i) => i === 0 ? ctx.moveTo(c[0], c[1]) : ctx.lineTo(c[0], c[1])); ctx.closePath(); ctx.stroke();
          for (let i = 0; i < 4; i++) { ctx.beginPath(); ctx.moveTo(bs[i][0], bs[i][1]); ctx.lineTo(ts[i][0], ts[i][1]); ctx.stroke(); }
          ctx.setLineDash([]);
          const lab = project([4, 4, TOP], 3, W, H);
          ctx.fillStyle = '#15803d'; ctx.font = 'bold 12px Inter, sans-serif';
          ctx.fillText('V: everything on or above the floor (z ≥ 0)', Math.min(lab[0], W - 280), Math.max(lab[1] - 8, 16));
        } else if (lvl.setType === 'plane_origin_3d') {
          // Wireframe mesh for z = 0.5x + 0.5y
          ctx.strokeStyle = 'rgba(37, 99, 235, 0.40)';
          ctx.lineWidth = 1.5;
          for (let g = -4; g <= 4; g += 1) {
            const a1 = project([g, -4, 0.5 * g - 2], 3, W, H);
            const b1 = project([g,  4, 0.5 * g + 2], 3, W, H);
            ctx.beginPath(); ctx.moveTo(a1[0], a1[1]); ctx.lineTo(b1[0], b1[1]); ctx.stroke();

            const a2 = project([-4, g, -2 + 0.5 * g], 3, W, H);
            const b2 = project([ 4, g,  2 + 0.5 * g], 3, W, H);
            ctx.beginPath(); ctx.moveTo(a2[0], a2[1]); ctx.lineTo(b2[0], b2[1]); ctx.stroke();
          }
        }
      }
      ctx.restore();
    }

    function drawCanvas() {
      const canvas = document.getElementById('vecCanvas');
      if (!canvas) return;
      fitCanvasWidth();
      const ctx = canvas.getContext('2d');
      const W = canvas.width, H = canvas.height;
      const lvl = currentLevel();
      const dim = lvl.dim;

      ctx.clearRect(0, 0, W, H);

      // 1. Draw coordinate grid (2D or 3D)
      if (dim === 2) {
        ctx.strokeStyle = '#f1f5f9';
    ctx.lineWidth = 1;
    const GMAX = Math.ceil((W / 2) / SCALE_2D) + 1;   // enough grid lines to fill the canvas at any zoom
    const LSTEP = SCALE_2D >= 30 ? 2 : (SCALE_2D >= 16 ? 5 : 10);
    for (let g = -GMAX; g <= GMAX; g++) {
      const px = project([g, 0, 0], 2, W, H)[0];
      const py = project([0, g, 0], 2, W, H)[1];
      ctx.beginPath(); ctx.moveTo(px, 0); ctx.lineTo(px, H); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(0, py); ctx.lineTo(W, py); ctx.stroke();
    }
    const orig = project([0, 0, 0], 2, W, H);
    ctx.strokeStyle = '#94a3b8';
    ctx.lineWidth = 1.8;
    ctx.beginPath(); ctx.moveTo(0, orig[1]); ctx.lineTo(W, orig[1]); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(orig[0], 0); ctx.lineTo(orig[0], H); ctx.stroke();

    ctx.fillStyle = '#64748b';
    ctx.font = '11px Inter, sans-serif';
    for (let g = -Math.floor(GMAX / LSTEP) * LSTEP; g <= GMAX; g += LSTEP) {
      if (g === 0) continue;
      const pX = project([g, 0, 0], 2, W, H);
      const pY = project([0, g, 0], 2, W, H);
      ctx.fillText(g, pX[0] - 5, orig[1] + 15);
      ctx.fillText(g, orig[0] + 6, pY[1] + 4);
    }
  }

  // ---------------------------------------------------------------------------
  // Depth handling for 3D: the floor (z = 0) is drawn as a semi-opaque sheet.
  // Anything on the far side of the floor (below it when viewed from above,
  // above it when viewed from below) is drawn FIRST so the sheet covers it;
  // everything on the viewer's side is drawn AFTER, on top of the sheet.
  // ---------------------------------------------------------------------------
  const is3D = dim === 3;
  const fromAbove = Math.sin(state.camPitch) >= 0;
  const sideOf = z => (!is3D) ? 'all' : ((fromAbove ? z < -1e-6 : z > 1e-6) ? 'hidden' : 'visible');
  const inPass = (pass, side) => pass === 'all' || side === 'all' || pass === side;
  const lerp3 = (a, b, t) => [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];

  // Split a 3D segment where it pierces the floor; each piece is tagged with its side
  function splitAtFloor(a, b) {
    if (!is3D) return [{ p: a, q: b, side: 'all', hasTip: true }];
    const za = a[2], zb = b[2];
    if ((za > 1e-6 && zb < -1e-6) || (za < -1e-6 && zb > 1e-6)) {
      const m = lerp3(a, b, za / (za - zb));
      return [{ p: a, q: m, side: sideOf(za), hasTip: false }, { p: m, q: b, side: sideOf(zb), hasTip: true }];
    }
    return [{ p: a, q: b, side: sideOf((za + zb) / 2), hasTip: true }];
  }
  function drawLine(p0, p1, color, width) {
    ctx.save();
    ctx.strokeStyle = color; ctx.lineWidth = width;
    ctx.beginPath(); ctx.moveTo(p0[0], p0[1]); ctx.lineTo(p1[0], p1[1]); ctx.stroke();
    ctx.restore();
  }

  // ---------------------------------------------------------------------------
  // Bounding box (like Desmos 3D / matplotlib): the cube [-BOX, BOX]^3.
  // The 3 walls facing AWAY from the viewer are shaded with a faint grid and drawn
  // first (the corner of the room behind the plot); the edges nearest the viewer
  // are drawn last, on top of everything. Which walls are shaded flips as you rotate,
  // which tells your eye where you are looking from.
  // ---------------------------------------------------------------------------
  const BOX = 4.5;
  const toViewer = [
    -Math.sin(state.camYaw) * Math.cos(state.camPitch),
    -Math.cos(state.camYaw) * Math.cos(state.camPitch),
     Math.sin(state.camPitch)
  ];
  // Face (axis k, sign s) is a back wall if its outward normal points away from the viewer
  const isBackFace = (k, s) => s * toViewer[k] < 0;

  // Painter's order: draw the target and the vectors together, farthest from the viewer first,
  // so whichever is nearer ends up on top. A vector's depth is measured at its midpoint;
  // depth = point projected onto the toward-viewer direction (bigger = closer).
  // (In 2D there is no depth: target first, then vectors.)
  function drawObjects(pass) {
    const depthOfPt = p => p[0] * toViewer[0] + p[1] * toViewer[1] + p[2] * toViewer[2];
    const items = state.vecs.map((v, i) => {
      const tip = getVecTip(v);
      const mid = [(v.tail[0] + tip[0]) / 2, (v.tail[1] + tip[1]) / 2, (v.tail[2] + tip[2]) / 2];
      return { kind: 'vec', i: i, depth: is3D ? depthOfPt(mid) : 0 };
    });
    if (activePanel === 'panel1' && lvl.target) {
      const t = is3D ? lvl.target : [lvl.target[0], lvl.target[1], 0];
      items.push({ kind: 'target', depth: is3D ? depthOfPt(t) : -Infinity });
    }
    items.sort((a, b) => a.depth - b.depth);
    items.forEach(it => {
      if (it.kind === 'target') drawTarget(pass);
      else drawVector(state.vecs[it.i], it.i, pass);
    });
  }
  const boxPt = (k, s, a, ua, b, ub) => { const p = [0, 0, 0]; p[k] = s * BOX; p[a] = ua; p[b] = ub; return p; };

  function drawBoxBack() {
    ctx.save();
    for (let k = 0; k < 3; k++) {
      for (const s of [-1, 1]) {
        if (!isBackFace(k, s)) continue;
        const a = (k + 1) % 3, b = (k + 2) % 3;
        const poly = [[-BOX, -BOX], [BOX, -BOX], [BOX, BOX], [-BOX, BOX]].map(([u, w]) => project(boxPt(k, s, a, u, b, w), 3, W, H));
        ctx.fillStyle = 'rgba(226, 232, 240, 0.14)';
        ctx.beginPath();
        poly.forEach((c, i) => i === 0 ? ctx.moveTo(c[0], c[1]) : ctx.lineTo(c[0], c[1]));
        ctx.closePath(); ctx.fill();
        // light grid on the wall
        ctx.strokeStyle = 'rgba(203, 213, 225, 0.30)'; ctx.lineWidth = 0.7;
        for (let g = -4; g <= 4; g++) {
          const p1 = project(boxPt(k, s, a, g, b, -BOX), 3, W, H), p2 = project(boxPt(k, s, a, g, b, BOX), 3, W, H);
          ctx.beginPath(); ctx.moveTo(p1[0], p1[1]); ctx.lineTo(p2[0], p2[1]); ctx.stroke();
          const q1 = project(boxPt(k, s, a, -BOX, b, g), 3, W, H), q2 = project(boxPt(k, s, a, BOX, b, g), 3, W, H);
          ctx.beginPath(); ctx.moveTo(q1[0], q1[1]); ctx.lineTo(q2[0], q2[1]); ctx.stroke();
        }
      }
    }
    drawBoxEdges(true);
    ctx.restore();
  }

  // The 12 cube edges. An edge is a back edge if both faces it touches are back walls.
  function drawBoxEdges(backPass) {
    ctx.save();
    ctx.strokeStyle = backPass ? 'rgba(148, 163, 184, 0.35)' : 'rgba(100, 116, 139, 0.45)';
    ctx.lineWidth = backPass ? 1 : 1.1;
    for (let run = 0; run < 3; run++) {
      const k1 = (run + 1) % 3, k2 = (run + 2) % 3;
      for (const s1 of [-1, 1]) for (const s2 of [-1, 1]) {
        const back = isBackFace(k1, s1) && isBackFace(k2, s2);
        if (back !== backPass) continue;
        const p = [0, 0, 0], q = [0, 0, 0];
        p[k1] = q[k1] = s1 * BOX; p[k2] = q[k2] = s2 * BOX;
        p[run] = -BOX; q[run] = BOX;
        const a = project(p, 3, W, H), b = project(q, 3, W, H);
        ctx.beginPath(); ctx.moveTo(a[0], a[1]); ctx.lineTo(b[0], b[1]); ctx.stroke();
      }
    }
    ctx.restore();
  }

  // Panel 1 target marker (drawn in the pass matching its side of the floor)
  function drawTarget(pass) {
    if (!(activePanel === 'panel1' && lvl.target)) return;
    const tPt = dim === 3 ? lvl.target : [lvl.target[0], lvl.target[1], 0];
    if (!inPass(pass, sideOf(tPt[2]))) return;
    const tScr = project(tPt, dim, W, H);
    if (dim === 3) {
      const tFl = project([tPt[0], tPt[1], 0], 3, W, H);
      ctx.save();
      ctx.setLineDash([3, 3]); ctx.strokeStyle = '#f59e0b';
      ctx.beginPath(); ctx.moveTo(tFl[0], tFl[1]); ctx.lineTo(tScr[0], tScr[1]); ctx.stroke();
      ctx.beginPath(); ctx.arc(tFl[0], tFl[1], 4, 0, Math.PI * 2); ctx.stroke();
      ctx.restore();
    }
    ctx.save();
    ctx.fillStyle = '#f59e0b';
    ctx.strokeStyle = '#b45309';
    ctx.lineWidth = 2;
    ctx.beginPath(); ctx.arc(tScr[0], tScr[1], 9, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
    ctx.fillStyle = '#ffffff';
    ctx.beginPath(); ctx.arc(tScr[0], tScr[1], 3.5, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = '#92400e';
    ctx.font = 'bold 12px Inter, sans-serif';
    ctx.fillText(`Target T(${fmtPt(lvl.target, dim)})`, tScr[0] + 12, tScr[1] - 6);
    ctx.restore();
  }

  // One vector, restricted to the parts belonging to this pass ('hidden', 'visible', or 'all' in 2D)
  function drawVector(v, i, pass) {
    const col  = COLORS[i % COLORS.length];
    const name = (activePanel === 'panel2') ? P2_NAMES[i] : NAMES[i];
    if (isZeroBase(v)) return;

    const tail = v.tail;
    const tip  = getVecTip(v);
    const tailScr = project(tail, dim, W, H);
    const tipScr  = project(tip, dim, W, H);
    const scalingMode = !(activePanel === 'panel2' && state.phase === 1);

    // Faint dashed guide showing the line this vector can stretch along (drawn under everything)
    if (scalingMode && inPass(pass, is3D ? 'hidden' : 'all')) {
      const sA = project([tail[0] - v.base[0] * 3.5, tail[1] - v.base[1] * 3.5, tail[2] - v.base[2] * 3.5], dim, W, H);
      const sB = project([tail[0] + v.base[0] * 3.5, tail[1] + v.base[1] * 3.5, tail[2] + v.base[2] * 3.5], dim, W, H);
      ctx.save();
      ctx.strokeStyle = col; ctx.globalAlpha = 0.20; ctx.lineWidth = 1.5; ctx.setLineDash([4, 4]);
      ctx.beginPath(); ctx.moveTo(sA[0], sA[1]); ctx.lineTo(sB[0], sB[1]); ctx.stroke();
      ctx.restore();
    }

    if (is3D) {
      const xyTailScr = project([tail[0], tail[1], 0], 3, W, H);
      const xyTipScr  = project([tip[0], tip[1], 0], 3, W, H);

      // Vertical drop lines from the floor to the tail and tip (each on its own side)
      ctx.save();
      ctx.strokeStyle = col + '88'; ctx.lineWidth = 1.5; ctx.setLineDash([3, 3]);
      if (Math.abs(tail[2]) > 0.02 && inPass(pass, sideOf(tail[2]))) {
        ctx.beginPath(); ctx.moveTo(xyTailScr[0], xyTailScr[1]); ctx.lineTo(tailScr[0], tailScr[1]); ctx.stroke();
      }
      if (inPass(pass, sideOf(tip[2]))) {
        ctx.beginPath(); ctx.moveTo(xyTipScr[0], xyTipScr[1]); ctx.lineTo(tipScr[0], tipScr[1]); ctx.stroke();
      }
      ctx.restore();

      // Shadow on the floor + draggable floor ring lie ON the floor, so draw them on top of it
      if (inPass(pass, 'visible')) {
        drawArrow(ctx, xyTailScr, xyTipScr, col + '77', 2.2, true);
        const isHoverXY = state.hover && state.hover.idx === i && state.hover.part === 'xy';
        ctx.save();
        ctx.fillStyle = '#ffffff';
        ctx.strokeStyle = col;
        ctx.lineWidth = isHoverXY ? 3.5 : 2.5;
        ctx.beginPath(); ctx.arc(xyTipScr[0], xyTipScr[1], isHoverXY ? 8 : 6.5, 0, Math.PI * 2);
        ctx.fill(); ctx.stroke();
        ctx.fillStyle = col; ctx.font = 'bold 10px Inter, sans-serif';
        ctx.fillText(`${name}_xy`, xyTipScr[0] + 9, xyTipScr[1] + 4);
        ctx.restore();
      }
    }

    // Main vector arrow, split where it passes through the floor
    const isOutsideP2 = (activePanel === 'panel2' && state.phase === 1 && !isInSetW(v.freeTip, lvl));
    const mainColor   = isOutsideP2 ? '#dc2626' : col;
    splitAtFloor(tail, tip).forEach(seg => {
      if (!inPass(pass, seg.side)) return;
      const a = project(seg.p, dim, W, H), b = project(seg.q, dim, W, H);
      if (seg.hasTip) drawArrow(ctx, a, b, mainColor, 3.6, false);
      else drawLine(a, b, mainColor, 3.6);
    });

    // Tail joint circle (shows tip-to-tail connection clearly)
    if (inPass(pass, sideOf(tail[2]))) {
      ctx.save();
      ctx.fillStyle = '#ffffff'; ctx.strokeStyle = mainColor; ctx.lineWidth = 2;
      ctx.beginPath(); ctx.arc(tailScr[0], tailScr[1], 4.5, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
      ctx.restore();
    }

    // Head drag ring, ghost handle, and label go with the tip's side
    if (inPass(pass, sideOf(tip[2]))) {
      const isHoverHead = state.hover && state.hover.idx === i && state.hover.part === 'head';
      ctx.save();
      ctx.strokeStyle = mainColor;
      ctx.fillStyle   = isHoverHead ? mainColor : 'rgba(255,255,255,0.85)';
      ctx.lineWidth   = 2.2;
      ctx.beginPath();
      ctx.arc(tipScr[0], tipScr[1], isHoverHead ? 8.5 : 6.5, 0, Math.PI * 2);
      ctx.fill(); ctx.stroke();

      if (scalingMode && Math.abs(v.c) < 0.15) {
        const gPt = project([tail[0] + v.base[0] * 0.45, tail[1] + v.base[1] * 0.45, tail[2] + v.base[2] * 0.45], dim, W, H);
        ctx.strokeStyle = mainColor; ctx.setLineDash([2, 2]);
        ctx.beginPath(); ctx.arc(gPt[0], gPt[1], 6, 0, Math.PI * 2); ctx.stroke();
      }

      ctx.fillStyle = mainColor;
      ctx.font = 'bold 12px Inter, sans-serif';
      const lbl = scalingMode
        ? `${fmtNum(v.c)}·${name}${dim === 3 ? ' [z]' : ''}`
        : `${name}(${fmtPt(v.freeTip, dim)})${dim === 3 ? ' [z]' : ''}`;
      ctx.fillText(lbl, tipScr[0] + 10, tipScr[1] - 8);
      ctx.restore();
    }
  }

  // ---- 3D: far-side content first, then the floor sheet, then the near side ----
  if (is3D) {
    drawBoxBack();
    const o = project([0, 0, 0], 3, W, H);
    const zNeg = project([0, 0, -4.5], 3, W, H), zPos = project([0, 0, 4.5], 3, W, H);
    // The half of the z-axis on the far side of the floor
    if (fromAbove) drawLine(zNeg, o, '#0f172a', 2.2);
    else drawArrow(ctx, o, zPos, '#0f172a', 2.2);
    drawObjects('hidden');

    // The floor sheet: semi-opaque, so far-side content shows through only faintly
    const fc = [[-4.5, -4.5, 0], [4.5, -4.5, 0], [4.5, 4.5, 0], [-4.5, 4.5, 0]].map(p => project(p, 3, W, H));
    ctx.save();
    ctx.fillStyle = 'rgba(241, 245, 249, 0.82)';
    ctx.beginPath();
    fc.forEach((c, k) => k === 0 ? ctx.moveTo(c[0], c[1]) : ctx.lineTo(c[0], c[1]));
    ctx.closePath(); ctx.fill();
    ctx.strokeStyle = '#cbd5e1'; ctx.lineWidth = 1.2; ctx.stroke();
    ctx.restore();

    // Floor grid
    ctx.strokeStyle = '#d5dde7';
    ctx.lineWidth = 1;
    for (let g = -4; g <= 4; g++) {
      const a1 = project([g, -4, 0], 3, W, H), b1 = project([g, 4, 0], 3, W, H);
      ctx.beginPath(); ctx.moveTo(a1[0], a1[1]); ctx.lineTo(b1[0], b1[1]); ctx.stroke();
      const a2 = project([-4, g, 0], 3, W, H), b2 = project([4, g, 0], 3, W, H);
      ctx.beginPath(); ctx.moveTo(a2[0], a2[1]); ctx.lineTo(b2[0], b2[1]); ctx.stroke();
    }
    // x and y axes lie in the floor
    const xNeg = project([-4.5, 0, 0], 3, W, H), xPos = project([4.5, 0, 0], 3, W, H);
    const yNeg = project([0, -4.5, 0], 3, W, H), yPos = project([0, 4.5, 0], 3, W, H);
    drawArrow(ctx, xNeg, xPos, '#64748b', 1.8);
    drawArrow(ctx, yNeg, yPos, '#64748b', 1.8);
    // The half of the z-axis on the viewer's side
    if (fromAbove) drawArrow(ctx, o, zPos, '#0f172a', 2.2);
    else drawLine(zNeg, o, '#0f172a', 2.2);

    ctx.fillStyle = '#334155';
    ctx.font = 'bold 12px Inter, sans-serif';
    ctx.fillText('+X', xPos[0] + 6, xPos[1] + 4);
    ctx.fillText('+Y', yPos[0] + 6, yPos[1] + 4);
    ctx.fillStyle = fromAbove ? '#334155' : '#94a3b8';
    ctx.fillText('+Z (Vertical)', zPos[0] - 32, zPos[1] - 8);
  }

  // 2. Panel 2 Set Overlay
  if (activePanel === 'panel2') {
    drawSetOverlay(ctx, lvl, W, H);
  }

  // 3. Draw Origin Marker
  const origScr = project([0, 0, 0], dim, W, H);
  ctx.save();
  ctx.fillStyle = activePanel === 'panel3' ? '#f59e0b' : '#0f172a';
  ctx.beginPath();
  ctx.arc(origScr[0], origScr[1], activePanel === 'panel3' ? 7 : 5, 0, Math.PI * 2);
  ctx.fill();
  if (activePanel === 'panel3') {
    ctx.strokeStyle = '#fef3c7'; ctx.lineWidth = 2.5; ctx.stroke();
    ctx.fillStyle = '#b45309'; ctx.font = 'bold 12px Inter, sans-serif';
    ctx.fillText('ORIGIN GOAL (0,0)', origScr[0] + 10, origScr[1] + 16);
  }
  ctx.restore();

  // 4-5. Target + vectors, depth-sorted (near side of the floor in 3D, everything in 2D)
  drawObjects(is3D ? 'visible' : 'all');

  // 6. Highlight Escaped Resultant Point in Panel 2 Phase 2
  if (activePanel === 'panel2' && state.phase === 2) {
    const st = evaluateStatus();
    if (st.ok && st.escapedTip) {
      const escScr = project(st.escapedTip, dim, W, H);
      ctx.save();
      ctx.strokeStyle = '#16a34a'; ctx.fillStyle = 'rgba(22, 163, 74, 0.22)'; ctx.lineWidth = 3;
      ctx.beginPath(); ctx.arc(escScr[0], escScr[1], 13, 0, Math.PI * 2); ctx.fill(); ctx.stroke();
      ctx.fillStyle = '#15803d'; ctx.font = 'bold 12px Inter, sans-serif';
      ctx.fillText(`ESCAPED ${lvl.setName}!`, escScr[0] + 15, escScr[1] + 4);
      ctx.restore();
    }
  }

  // 7. Front edges of the 3D bounding box go on top of everything
  if (is3D) drawBoxEdges(false);
  }

// Listen to navbar tab switches in bslib
document.addEventListener('shown.bs.tab', function(e) {
  const targetVal = e.target.getAttribute('data-value');
  if (targetVal === 'panel1' || targetVal === 'panel2' || targetVal === 'panel3') {
    mountWorkspace(targetVal);
  }
});

document.addEventListener('DOMContentLoaded', function() {
  setTimeout(() => mountWorkspace('panel1'), 80);
});
})();
"))
)

